                if not files_only:
                    prefix = ""
                    if multiple_files:
                        prefix += filename + ":"
                    if show_line_numbers:
                        prefix += str(index) + ":"
                    output.append(prefix + line)
        if files_only and matched_any:
            output.append(filename)

    return "".join(line + "\n" for line in output)
